if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'profile';
 if($action==='profile'){$name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$users=read_data('users.json',[]);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$notice='Nama dan email yang valid wajib diisi.';else{$exists=false;foreach($users as &$u){if((int)$u['id']===$user['id']){$u['name']=$name;$u['email']=$email;}elseif(mb_strtolower($u['email'])===$email)$exists=true;}unset($u);if($exists)$notice='Email sudah digunakan akun lain.';else{write_data('users.json',$users);$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;$user=current_user();log_activity('Profil diperbarui','Nama atau email akun diperbarui','success');$notice='Profil berhasil disimpan.';}}}
 if($action==='password'){$old=$_POST['old_password']??'';$new=$_POST['new_password']??'';$users=read_data('users.json',[]);$ok=false;foreach($users as &$u)if((int)$u['id']===$user['id']&&password_verify($old,$u['password_hash'])&&strlen($new)>=8){$u['password_hash']=password_hash($new,PASSWORD_DEFAULT);$ok=true;}unset($u);if($ok){write_data('users.json',$users);$notice='Kata sandi berhasil diperbarui.';}else$notice='Kata sandi lama tidak cocok atau kata sandi baru kurang dari 8 karakter.';}
 if($action==='preferences'){$_SESSION['preferences']=['weekly_digest'=>isset($_POST['weekly_digest']),'wei_alert'=>isset($_POST['wei_alert'])];write_data('preferences-'.$user['id'].'.json',$_SESSION['preferences']);$notice='Preferensi notifikasi disimpan.';}
}
